"""The tickets API: create, list, get, update."""
from contextlib import asynccontextmanager

from fastapi import Depends, FastAPI, HTTPException, Query, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.auth import require_api_key
from app.db import Ticket, get_db, init_db
from app.schemas import Status, TicketCreate, TicketOut, TicketUpdate


@asynccontextmanager
async def lifespan(app: FastAPI):
    init_db()  # create tables on startup (a real project would use Alembic migrations)
    yield


app = FastAPI(title="Tickets API", version="1.0.0", lifespan=lifespan)


@app.post("/tickets", response_model=TicketOut, status_code=status.HTTP_201_CREATED,
          dependencies=[Depends(require_api_key)])
def create_ticket(body: TicketCreate, db: Session = Depends(get_db)) -> Ticket:
    ticket = Ticket(title=body.title, description=body.description, priority=body.priority.value)
    db.add(ticket)
    db.commit()
    db.refresh(ticket)
    return ticket


@app.get("/tickets", response_model=list[TicketOut], dependencies=[Depends(require_api_key)])
def list_tickets(
    status_filter: Status | None = Query(default=None, alias="status"),
    limit: int = Query(default=20, ge=1, le=100),
    offset: int = Query(default=0, ge=0),
    db: Session = Depends(get_db),
) -> list[Ticket]:
    stmt = select(Ticket).order_by(Ticket.id).limit(limit).offset(offset)
    if status_filter is not None:
        stmt = stmt.where(Ticket.status == status_filter.value)
    return list(db.scalars(stmt))


def _get_or_404(db: Session, ticket_id: int) -> Ticket:
    ticket = db.get(Ticket, ticket_id)
    if ticket is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, f"Ticket {ticket_id} not found")
    return ticket


@app.get("/tickets/{ticket_id}", response_model=TicketOut, dependencies=[Depends(require_api_key)])
def get_ticket(ticket_id: int, db: Session = Depends(get_db)) -> Ticket:
    return _get_or_404(db, ticket_id)


@app.patch("/tickets/{ticket_id}", response_model=TicketOut, dependencies=[Depends(require_api_key)])
def update_ticket(ticket_id: int, body: TicketUpdate, db: Session = Depends(get_db)) -> Ticket:
    ticket = _get_or_404(db, ticket_id)
    # exclude_unset: only touch fields the client actually sent.
    for field, value in body.model_dump(exclude_unset=True).items():
        if value is None:
            raise HTTPException(422, f"{field} cannot be null")
        setattr(ticket, field, getattr(value, "value", value))
    db.commit()
    db.refresh(ticket)
    return ticket

"""A fake paginated "customer API" that misbehaves on purpose.

It behaves like an HTTP API: get_page(cursor) returns (status_code, body, headers).
You can script failures (429 rate limits, 500 errors) and it always serves a few
malformed rows, so the client has to cope with all three.
"""
import base64
import random


def encode_cursor(offset: int) -> str:
    # Real APIs return opaque cursors; clients must never parse them.
    return base64.urlsafe_b64encode(f"offset:{offset}".encode()).decode()


def decode_cursor(cursor: str | None) -> int:
    if not cursor:
        return 0
    return int(base64.urlsafe_b64decode(cursor.encode()).decode().split(":")[1])


def make_customers(n: int = 25, seed: int = 7) -> list[dict]:
    """Deterministic sample data. Every 6th row is broken in a different way."""
    rng = random.Random(seed)
    plans = ["free", "pro", "enterprise"]
    rows = []
    for i in range(1, n + 1):
        row = {
            "id": i,
            "name": f"Customer {i}",
            "email": f"user{i}@example.com",
            "plan": rng.choice(plans),
            "signup_date": f"2024-{rng.randint(1, 12):02d}-{rng.randint(1, 28):02d}",
        }
        if i % 6 == 0:
            broken = [
                lambda r: r.update(email="not-an-email"),
                lambda r: r.pop("name"),
                lambda r: r.update(signup_date="31/02/2024"),
                lambda r: r.update(plan="platinum"),
            ]
            broken[(i // 6 - 1) % len(broken)](row)
        rows.append(row)
    return rows


class MockCustomerAPI:
    def __init__(self, rows: list[dict] | None = None, page_size: int = 10,
                 failures: list[int] | None = None):
        self.rows = rows if rows is not None else make_customers()
        self.page_size = page_size
        self.failures = list(failures or [])  # status codes to return, in order, before succeeding
        self.calls = 0

    def get_page(self, cursor: str | None = None) -> tuple[int, dict, dict]:
        self.calls += 1
        if self.failures:
            code = self.failures.pop(0)
            headers = {"Retry-After": "1"} if code == 429 else {}
            return code, {"error": "simulated failure"}, headers
        start = decode_cursor(cursor)
        chunk = self.rows[start:start + self.page_size]
        end = start + len(chunk)
        next_cursor = encode_cursor(end) if end < len(self.rows) else None
        return 200, {"data": chunk, "next_cursor": next_cursor}, {}

"""SQLite storage: good rows, dead-letter rows, and the cursor checkpoint."""
import json
import sqlite3

from ingest.models import Customer

SCHEMA = """
CREATE TABLE IF NOT EXISTS customers (
    id INTEGER PRIMARY KEY, name TEXT, email TEXT, plan TEXT, signup_date TEXT
);
CREATE TABLE IF NOT EXISTS dead_letter (
    id INTEGER PRIMARY KEY AUTOINCREMENT, raw TEXT, error TEXT, cursor TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS checkpoint (
    name TEXT PRIMARY KEY, cursor TEXT, done INTEGER DEFAULT 0
);
"""


class Store:
    def __init__(self, path: str = "ingest.db", job: str = "customers"):
        self.conn = sqlite3.connect(path)
        self.conn.executescript(SCHEMA)
        self.job = job

    def load_checkpoint(self) -> tuple[str | None, bool]:
        row = self.conn.execute(
            "SELECT cursor, done FROM checkpoint WHERE name = ?", (self.job,)).fetchone()
        return (row[0], bool(row[1])) if row else (None, False)

    def save_page(self, good: list[Customer], bad: list[tuple[dict, str]],
                  page_cursor: str | None, next_cursor: str | None) -> None:
        """Write one page's rows AND the new checkpoint in a single transaction.

        If we crash mid-page, nothing from that page is committed and the cursor
        still points at it, so the rerun redoes exactly that page.
        """
        with self.conn:  # commits on success, rolls back on exception
            self.conn.executemany(
                # Upsert makes replays idempotent: re-ingesting a row never duplicates it.
                "INSERT INTO customers (id, name, email, plan, signup_date) VALUES (?,?,?,?,?) "
                "ON CONFLICT(id) DO UPDATE SET name=excluded.name, email=excluded.email, "
                "plan=excluded.plan, signup_date=excluded.signup_date",
                [(c.id, c.name, c.email, c.plan, c.signup_date.isoformat()) for c in good],
            )
            self.conn.executemany(
                "INSERT INTO dead_letter (raw, error, cursor) VALUES (?,?,?)",
                [(json.dumps(raw), err, page_cursor) for raw, err in bad],
            )
            self.conn.execute(
                "INSERT INTO checkpoint (name, cursor, done) VALUES (?,?,?) "
                "ON CONFLICT(name) DO UPDATE SET cursor=excluded.cursor, done=excluded.done",
                (self.job, next_cursor, int(next_cursor is None)),
            )

    def count(self, table: str) -> int:
        assert table in {"customers", "dead_letter"}
        return self.conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]

"""The resilient ingestion client: paginate, retry, validate, store, checkpoint."""
import logging

from pydantic import ValidationError
from tenacity import (Retrying, before_sleep_log, retry_if_exception_type,
                      stop_after_attempt, wait_exponential_jitter)

from ingest.models import Customer
from ingest.store import Store

log = logging.getLogger("ingest")
RETRYABLE = {429, 500, 502, 503, 504}


class RetryableHTTPError(Exception):
    def __init__(self, status: int):
        super().__init__(f"retryable HTTP {status}")
        self.status = status


class PermanentHTTPError(Exception):
    pass


def fetch_page(api, cursor, max_attempts: int = 5, wait=None) -> dict:
    """Call the API with exponential backoff plus jitter on 429/5xx."""
    retryer = Retrying(
        retry=retry_if_exception_type(RetryableHTTPError),
        stop=stop_after_attempt(max_attempts),
        # 0.5s, 1s, 2s, 4s ... capped at 10s, each plus up to 1s of random jitter so
        # many clients don't retry in lockstep (the "thundering herd").
        wait=wait or wait_exponential_jitter(initial=0.5, max=10, jitter=1),
        before_sleep=before_sleep_log(log, logging.WARNING),
        reraise=True,  # surface the real error, not tenacity's RetryError wrapper
    )
    for attempt in retryer:
        with attempt:
            status, body, _headers = api.get_page(cursor)
            if status in RETRYABLE:
                raise RetryableHTTPError(status)
            if status != 200:
                raise PermanentHTTPError(f"HTTP {status}: {body}")  # 4xx: retrying won't help
            return body
    raise AssertionError("unreachable")


def run_ingestion(api, store: Store, max_attempts: int = 5, wait=None) -> dict:
    cursor, done = store.load_checkpoint()
    if done:
        log.info("already complete; nothing to do")
        return {"pages": 0, "good": 0, "bad": 0}
    stats = {"pages": 0, "good": 0, "bad": 0}
    while True:
        body = fetch_page(api, cursor, max_attempts, wait)
        good, bad = [], []
        for raw in body.get("data", []):
            try:
                good.append(Customer.model_validate(raw))
            except ValidationError as e:
                bad.append((raw, "; ".join(f"{'.'.join(map(str, err['loc']))}: {err['msg']}"
                                           for err in e.errors())))
        next_cursor = body.get("next_cursor")
        store.save_page(good, bad, cursor, next_cursor)
        stats["pages"] += 1
        stats["good"] += len(good)
        stats["bad"] += len(bad)
        log.info("page done: %d good, %d bad", len(good), len(bad))
        if next_cursor is None:
            return stats
        cursor = next_cursor

